code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    paths = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            if color == 1:
                cells = [(r, c+i) for i in (1,2)] + [(r-1,c+2)]
            elif color == 2:
                cells = [(r,c-i) for i in range(1,5)] + [(r,c-4)]
            elif color == 3:
                cells = [(r+i,c) for i in range(1,4)] + [(r+3,c)]
            elif color == 6:
                cells = [(r-i,c) for i in range(1,7)] + [(r-6,c)]
            else:
                continue
            valid = [(rr,cc) for rr,cc in cells if 0 <= rr < h and 0 <= cc < w]
            for rr,cc in valid:
                out[rr][cc] = 5
            if valid:
                rr,cc=valid[-1]
                out[rr][cc]=color
            paths.append({(rr,cc) for rr,cc in valid} | {(r,c)})
    intersections=set()
    for i in range(len(paths)):
        for j in range(i+1,len(paths)):
            intersections |= paths[i] & paths[j]
    for r,c in intersections:
        out[r][c]=4
        rr,cc=r+1,c-1
        while 0<=rr<h and 0<=cc<w:
            out[rr][cc]=4
            rr+=1;cc-=1
    return out
'''
